CREATE TABLE Book (
    Author VARCHAR(255),
    Book_Title VARCHAR(255),
    ISBN_Number VARCHAR(255) PRIMARY KEY,
    Publication_Year INTEGER,
    Publishing_House VARCHAR(255)
);

CREATE TABLE Type (
    Type_ID INTEGER PRIMARY KEY,
    Type_Name VARCHAR(255)
);

CREATE TABLE Tag (
    Tag_ID INTEGER PRIMARY KEY,
    Tag_Name VARCHAR(255)
);

CREATE TABLE Book_Type_Relation (
    ISBN_Number VARCHAR(255) NOT NULL,
    Type_ID INTEGER NOT NULL,
    PRIMARY KEY (ISBN_Number, Type_ID),
    FOREIGN KEY (ISBN_Number) REFERENCES Book(ISBN_Number),
    FOREIGN KEY (Type_ID) REFERENCES Type(Type_ID)
);

CREATE TABLE Book_Tag_Relation (
    ISBN_Number VARCHAR(255) NOT NULL,
    Tag_ID INTEGER NOT NULL,
    PRIMARY KEY (ISBN_Number, Tag_ID),
    FOREIGN KEY (ISBN_Number) REFERENCES Book(ISBN_Number),
    FOREIGN KEY (Tag_ID) REFERENCES Tag(Tag_ID)
);
